import { IHikingApproveDTO } from '../@types/DTO/hikingApprovers.dto.types';
import { IHikingApprove } from '../@types/hikingApprovers.types';

export const mapHikingApprove = (backData: IHikingApproveDTO): IHikingApprove => {
  return {
    id: +backData.id,
    user: {
      id: +backData.id_user,
      name: backData.user_name,
      surname: backData.user_surname,
      photo: backData.user_photo,
    },
    position: {
      id: +backData.id_position,
      name: backData.position_name,
    },
    entity_id: backData.entity_id ? +backData.entity_id : null,
    entity_type: backData.entity_type,
    created_at: new Date(backData.created_at),
  };
};
